"""NoSQL Injection Lab — Secure | CWE-943 | OWASP A03:2021"""
from __future__ import annotations
import os
from typing import Any
from flask import Flask, jsonify, request
from pydantic import BaseModel, ValidationError, field_validator

app = Flask(__name__)
app.secret_key = "lab-nosql-secure-key"

_USERS = [
    {"username": "alice", "password": "lab_alice_pass", "role": "user"},
    {"username": "bob",   "password": "lab_bob_pass",   "role": "user"},
    {"username": "admin", "password": "lab_admin_pass", "role": "admin"},
]

class LoginRequest(BaseModel):
    username: str
    password: str

    @field_validator("username", "password")
    @classmethod
    def must_be_string(cls, v: str) -> str:
        if v.startswith("$"): raise ValueError("Opérateurs non autorisés")
        if len(v) > 128: raise ValueError("Trop long")
        return v

